import{_ as i,a0 as r,w as e,s as o,I as n,x as t,a1 as a,A as l,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"關於 Ubuntu 20.04 你應該瞭解的事情 | LCTT x X-CMD","titleTemplate":false,"description":"關於 Ubuntu 20.04 你應該瞭解的事情 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關於 Ubuntu 20.04 你應該瞭解的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關於 Ubuntu 20.04 你應該瞭解的事情 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200422 Things You Should Know About Ubuntu 20.04","title":"關於 Ubuntu 20.04 你應該瞭解的事情","tag":"202004","desc":""},"relativePath":"202004/20200422 Things You Should Know About Ubuntu 20.04.md","filePath":"[post].md"}'),p={name:"202004/20200422 Things You Should Know About Ubuntu 20.04.md"};function d(U,u,f,m,T,h){const b=r("Link");return e(),o("div",null,[u[30]||(u[30]=n("h1",{id:"關於-ubuntu-20-04-你應該瞭解的事情",tabindex:"-1"},[t("關於 Ubuntu 20.04 你應該瞭解的事情 "),n("a",{class:"header-anchor",href:"#關於-ubuntu-20-04-你應該瞭解的事情","aria-label":"Permalink to “關於 Ubuntu 20.04 你應該瞭解的事情”"},"​")],-1)),n("p",null,[a(b,{href:"https://linux.cn/article-12142-1.html"},{default:l(()=>[...u[0]||(u[0]=[t("Ubuntu 20.04",-1)])]),_:1}),u[1]||(u[1]=t(" 已經發布，你可能對升級、安裝等有一些問題和疑問。",-1))]),u[31]||(u[31]=s('<p>我在各種社交媒體渠道上主持了一些問答環節，回答像你這樣的讀者的疑慮。我將列出這些關於 Ubuntu 20.04 的常見問題，並給出答案。我希望它能幫助你消除你的疑慮。如果你仍有問題，請隨時在下面的評論欄提問。</p><h3 id="ubuntu-20-04-已回覆的問題" tabindex="-1">Ubuntu 20.04：已回覆的問題 <a class="header-anchor" href="#ubuntu-20-04-已回覆的問題" aria-label="Permalink to “Ubuntu 20.04：已回覆的問題”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/04/ubuntu_20_04_faq.jpg?ssl=1" alt=""></p><p>為了澄清一下，這裏的一些答案也許受我個人意見的影響。如果你是一個有經驗的 Ubuntu 用户，有些問題聽起來可能有點愚蠢，但它對 Ubuntu 新用户不是這樣。</p><h4 id="ubuntu-20-04-何時發佈" tabindex="-1">Ubuntu 20.04 何時發佈？ <a class="header-anchor" href="#ubuntu-20-04-何時發佈" aria-label="Permalink to “Ubuntu 20.04 何時發佈？”">​</a></h4><p>Ubuntu 20.04 LTS 於 2020 年 4 月 23 日發佈。所有變種，如 Kubuntu、Lubuntu,、Xubuntu、Budgie、MATE 都將和 20.04 同一天發佈。</p><h4 id="ubuntu-20-04-的系統要求是什麼" tabindex="-1">Ubuntu 20.04 的系統要求是什麼？ <a class="header-anchor" href="#ubuntu-20-04-的系統要求是什麼" aria-label="Permalink to “Ubuntu 20.04 的系統要求是什麼？”">​</a></h4><p>對於默認的 GNOME 版本，應至少具有 4GB 的內存、2GHz 雙核處理器和至少 25GB 的磁盤空間。</p>',8)),n("p",null,[u[3]||(u[3]=t("其他 ",-1)),a(b,{href:"https://itsfoss.com/which-ubuntu-install/"},{default:l(()=>[...u[2]||(u[2]=[t("Ubuntu 變種",-1)])]),_:1}),u[4]||(u[4]=t("可能有不同的系統要求。",-1))]),u[32]||(u[32]=s('<h4 id="我可以在-32-位系統上使用-ubuntu-20-04-嗎" tabindex="-1">我可以在 32 位系統上使用 Ubuntu 20.04 嗎？ <a class="header-anchor" href="#我可以在-32-位系統上使用-ubuntu-20-04-嗎" aria-label="Permalink to “我可以在 32 位系統上使用 Ubuntu 20.04 嗎？”">​</a></h4><p>完全不行。你不能在 32 位系統上使用 Ubuntu 20.04。即使你使用的是 32 位 Ubuntu 18.04，也不能升級到 Ubuntu 20.04。32 位的系統 ISO 是以前用的。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/04/ubuntu-32-bit.jpg?ssl=1" alt="Error while upgrading 32-bit Ubuntu 18.04 to Ubuntu 20.04"></p><h4 id="我可以在-ubuntu-20-04-上使用-wine-嗎" tabindex="-1">我可以在 Ubuntu 20.04 上使用 Wine 嗎？ <a class="header-anchor" href="#我可以在-ubuntu-20-04-上使用-wine-嗎" aria-label="Permalink to “我可以在 Ubuntu 20.04 上使用 Wine 嗎？”">​</a></h4>',4)),n("p",null,[u[6]||(u[6]=t("是的，你仍然可以在 Ubuntu 20.04 上使用 Wine，因為仍然用於 Wine 和 ",-1)),a(b,{href:"https://itsfoss.com/steam-play/"},{default:l(()=>[...u[5]||(u[5]=[t("Steam Play",-1)])]),_:1}),u[7]||(u[7]=t(" 軟件包所需的 32 位庫。",-1))]),u[33]||(u[33]=s('<h4 id="我需要購買-ubuntu-20-04-或許可證" tabindex="-1">我需要購買 Ubuntu 20.04 或許可證？ <a class="header-anchor" href="#我需要購買-ubuntu-20-04-或許可證" aria-label="Permalink to “我需要購買 Ubuntu 20.04 或許可證？”">​</a></h4><p>不，Ubuntu 完全可以免費使用。你不必像在 Windows 中那樣購買許可證密鑰或激活 Ubuntu。</p><p>Ubuntu 的下載頁會請求你捐贈一些資金，如果你想為開發這個強大的操作系統捐錢，由你自己決定。</p><h4 id="gnome-版本是什麼" tabindex="-1">GNOME 版本是什麼？ <a class="header-anchor" href="#gnome-版本是什麼" aria-label="Permalink to “GNOME 版本是什麼？”">​</a></h4><p>Ubuntu 20.04 有 GNOME 3.36。</p><h4 id="ubuntu-20-04-的性能是否優於-ubuntu-18-04" tabindex="-1">Ubuntu 20.04 的性能是否優於 Ubuntu 18.04？ <a class="header-anchor" href="#ubuntu-20-04-的性能是否優於-ubuntu-18-04" aria-label="Permalink to “Ubuntu 20.04 的性能是否優於 Ubuntu 18.04？”">​</a></h4><p>是的，在幾個方面。Ubuntu 20.04 系統速度更快，甚至超快。我在下面這個視頻的 4:40 處展示了性能對比。</p>',7)),n("ul",null,[n("li",null,[a(b,{href:"https://img.linux.net.cn/static/video/Top%207%20Best%20Features%20You%27ll%20Love%20in%20Ubuntu%2020.04-lpq8pm_xkSE.mp4"},{default:l(()=>[...u[8]||(u[8]=[t("video",-1)])]),_:1})])]),u[34]||(u[34]=n("p",null,"在 GNOME 3.36 中，滾動、窗口動畫和其他 UI 元素更加流暢，提供了更流暢的體驗。",-1)),u[35]||(u[35]=n("h4",{id:"ubuntu-20-04-將支持多長時間",tabindex:"-1"},[t("Ubuntu 20.04 將支持多長時間？ "),n("a",{class:"header-anchor",href:"#ubuntu-20-04-將支持多長時間","aria-label":"Permalink to “Ubuntu 20.04 將支持多長時間？”"},"​")],-1)),u[36]||(u[36]=n("p",null,"它是一個長期支持（LTS）版本，與任何 LTS 版本一樣，它將在五年內得到支持。這意味着 Ubuntu 20.04 將在 2025 年 4 月之前獲得安全和維護更新。",-1)),u[37]||(u[37]=n("h4",{id:"升級到-ubuntu-20-04-時-是否會丟失數據",tabindex:"-1"},[t("升級到 Ubuntu 20.04 時，是否會丟失數據？ "),n("a",{class:"header-anchor",href:"#升級到-ubuntu-20-04-時-是否會丟失數據","aria-label":"Permalink to “升級到 Ubuntu 20.04 時，是否會丟失數據？”"},"​")],-1)),u[38]||(u[38]=n("p",null,"你可以從 Ubuntu 19.10 或 Ubuntu 18.04 升級到 Ubuntu 20.04。你無需創建 live USB 並從中安裝。你所需要的是一個良好的互聯網連接，來下載約 1.5GB 的數據。",-1)),u[39]||(u[39]=n("p",null,"從現有系統升級不會破壞你的文件。你應該會留有所有文件，並且大多數現有軟件應具有相同的版本或升級後的版本。",-1)),n("p",null,[u[10]||(u[10]=t("如果你使用了某些第三方工具或",-1)),a(b,{href:"https://itsfoss.com/ppa-guide/"},{default:l(()=>[...u[9]||(u[9]=[t("其他 PPA",-1)])]),_:1}),u[11]||(u[11]=t("，升級過程將禁用它們。如果 Ubuntu 20.04 可以使用這些其他存儲庫，那麼可以再次啓用它們。",-1))]),u[40]||(u[40]=s('<p>升級大約需要一個小時，重啓後，你將登錄到新版本。</p><p>雖然你的數據不會被觸碰，並且不會丟失系統文件和配置，但最好在外部設備備份重要數據。</p><h4 id="何時可以升級到-ubuntu-20-04" tabindex="-1">何時可以升級到 Ubuntu 20.04？ <a class="header-anchor" href="#何時可以升級到-ubuntu-20-04" aria-label="Permalink to “何時可以升級到 Ubuntu 20.04？”">​</a></h4><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/03/upgrade-ubuntu-20-04.jpg?ssl=1" alt=""></p><p>如果你正在使用 Ubuntu 19.10 並有正確的更新設置（如前面部分所述），那麼應在發佈後的幾天內通知你升級到 Ubuntu 20.04。</p><p>對於 Ubuntu 18.04 用户，可能需要幾周時間才能正式通知他們 Ubuntu 20.04 可用。可能，你可能會在第一個點版本 Ubuntu 20.04.1 後獲得提示。</p><h4 id="如果我升級到-ubuntu-20-04-我可以降級到-19-10-或-18-04-嗎" tabindex="-1">如果我升級到 Ubuntu 20.04，我可以降級到 19.10 或 18.04 嗎？ <a class="header-anchor" href="#如果我升級到-ubuntu-20-04-我可以降級到-19-10-或-18-04-嗎" aria-label="Permalink to “如果我升級到 Ubuntu 20.04，我可以降級到 19.10 或 18.04 嗎？”">​</a></h4>',7)),n("p",null,[u[13]||(u[13]=t("不行。雖然升級到新版本很容易，但無法選擇降級。如果你想回到 Ubuntu 18.04，你需要重新",-1)),a(b,{href:"https://itsfoss.com/install-ubuntu/"},{default:l(()=>[...u[12]||(u[12]=[t("安裝 Ubuntu 18.04",-1)])]),_:1}),u[14]||(u[14]=t("。",-1))]),u[41]||(u[41]=s('<h4 id="我使用的是-ubuntu-18-04-lts。我應該升級到-ubuntu-20-04-lts-嗎" tabindex="-1">我使用的是 Ubuntu 18.04 LTS。我應該升級到 Ubuntu 20.04 LTS 嗎？ <a class="header-anchor" href="#我使用的是-ubuntu-18-04-lts。我應該升級到-ubuntu-20-04-lts-嗎" aria-label="Permalink to “我使用的是 Ubuntu 18.04 LTS。我應該升級到 Ubuntu 20.04 LTS 嗎？”">​</a></h4><p>這取決於你。如果你對 Ubuntu 20.04 中的新功能印象深刻，並希望上手嘗試，那麼你應該升級。</p><p>如果你想要一個更穩定的系統，我建議等待第一個點版本 Ubuntu 20.04.1，新版本會有 bug 修復。20.04.1 通常在 Ubuntu 20.04 發佈後大約兩個月到來。</p><p>無論是那種情況，我都建議你或早或晚升級到 Ubuntu 20.04。Ubuntu 20.04 具有更新的內核、性能改進，尤其是倉庫中有更新版本的軟件。</p><p>在外部磁盤上進行備份，並且有良好的互聯網連接，升級不應成為問題。</p><h4 id="我應該重新安裝-ubuntu-20-04-還是從-18-04-19-10-升級到-ubuntu" tabindex="-1">我應該重新安裝 Ubuntu 20.04 還是從 18.04/19.10 升級到 Ubuntu？ <a class="header-anchor" href="#我應該重新安裝-ubuntu-20-04-還是從-18-04-19-10-升級到-ubuntu" aria-label="Permalink to “我應該重新安裝 Ubuntu 20.04 還是從 18.04/19.10 升級到 Ubuntu？”">​</a></h4><p>如果你可以選擇，請備份數據，並重新安裝 Ubuntu 20.04。</p><p>從現有版本升級到 20.04 是一個方便的選擇。然而，在我看來，它仍然保留有一些舊版本的痕跡/包。全新安裝更加乾淨。</p><h4 id="關於-ubuntu-20-04-的任何其他問題" tabindex="-1">關於 Ubuntu 20.04 的任何其他問題？ <a class="header-anchor" href="#關於-ubuntu-20-04-的任何其他問題" aria-label="Permalink to “關於 Ubuntu 20.04 的任何其他問題？”">​</a></h4><p>如果你對 Ubuntu 20.04 有任何疑問，請隨時在下面發表評論。如果你認為應該將其他信息添加到列表中，請讓我知道。</p><hr>',11)),n("p",null,[u[16]||(u[16]=t("via: ",-1)),a(b,{href:"https://itsfoss.com/ubuntu-20-04-faq/"},{default:l(()=>[...u[15]||(u[15]=[t("https://itsfoss.com/ubuntu-20-04-faq/",-1)])]),_:1})]),n("p",null,[u[21]||(u[21]=t("作者：",-1)),a(b,{href:"https://itsfoss.com/author/abhishek/"},{default:l(()=>[...u[17]||(u[17]=[t("Abhishek Prakash",-1)])]),_:1}),u[22]||(u[22]=t(" 選題：",-1)),a(b,{href:"https://github.com/lujun9972"},{default:l(()=>[...u[18]||(u[18]=[t("lujun9972",-1)])]),_:1}),u[23]||(u[23]=t(" 譯者：",-1)),a(b,{href:"https://github.com/geekpi"},{default:l(()=>[...u[19]||(u[19]=[t("geekpi",-1)])]),_:1}),u[24]||(u[24]=t(" 校對：",-1)),a(b,{href:"https://github.com/wxy"},{default:l(()=>[...u[20]||(u[20]=[t("wxy",-1)])]),_:1})]),n("p",null,[u[27]||(u[27]=t("本文由 ",-1)),a(b,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...u[25]||(u[25]=[t("LCTT",-1)])]),_:1}),u[28]||(u[28]=t(" 原創編譯，",-1)),a(b,{href:"https://linux.cn/"},{default:l(()=>[...u[26]||(u[26]=[t("Linux中國",-1)])]),_:1}),u[29]||(u[29]=t(" 榮譽推出",-1))])])}const g=i(p,[["render",d]]);export{S as __pageData,g as default};
